save_freq=${SAVE_FREQ:-20}
test_freq=${TEST_FREQ:-10}

project_name=${PROJECT_NAME:-verl_grpo_hy_v3}
experiment_name=${EXPERIMENT_NAME:-hy_v3_a3b_${INFER_BACKEND}_megatron}
